<section class="panel"><div class="panel-heading"><h2>Equipo y accesos</h2><a class="button small" href="#create-user"><?= icon('plus',16) ?> Crear usuario</a></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($rows as $u): ?><tr><td><?= e($u['name']) ?></td><td><?= e($u['email']) ?></td><td><?= e($u['role']) ?></td><td><?= badge($u['active'] ? 'active':'inactive') ?></td><td><?php if($u['id']!=user()['id']): ?><form method="post" data-confirm="Se cambiará el acceso de esta cuenta y se invalidarán sus sesiones."><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="button secondary small"><?= $u['active'] ? 'Desactivar':'Activar' ?></button></form><?php else: ?><small>Tu cuenta</small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<details class="panel form-panel" id="create-user"><summary>Crear cuenta del equipo</summary><form method="post" class="form-grid"><?= csrf_field() ?><?php field('name','Nombre completo'); field('email','Correo','','email'); choose('role_id','Rol',array_column($roles,'name','id')); field('password','Contraseña temporal','','password',true,'minlength="12" maxlength="72" autocomplete="new-password"'); ?><button class="button">Crear usuario</button></form></details>
<section class="panel form-panel"><h2>Permisos por rol</h2><p class="muted">Los permisos se comprueban en el servidor. Los permisos base de administración están protegidos.</p><div class="roles-grid"><?php foreach($roles as $r): if($r['name']==='Administrador') continue; ?><form method="post" class="role-card" data-confirm="Se modificarán los permisos de todas las cuentas con este rol."><?= csrf_field() ?><input type="hidden" name="action" value="role"><input type="hidden" name="role_id" value="<?= (int)$r['id'] ?>"><h3><?= e($r['name']) ?></h3><?php foreach($permissions as $p): $checked=(bool)array_filter($grants,fn($g)=>$g['role_id']==$r['id'] && $g['permission_id']==$p['id']); ?><label class="checkbox"><input type="checkbox" name="permissions[]" value="<?= (int)$p['id'] ?>" <?= $checked ? 'checked':'' ?>><?= e($modules[$p['name']][0] ?? $p['name']) ?></label><?php endforeach; ?><button class="button secondary small">Guardar permisos</button></form><?php endforeach; ?></div><form method="post" class="filters"><?= csrf_field() ?><input type="hidden" name="action" value="new_role"><?php field('name','Nombre de nuevo rol'); ?><button class="button secondary">Crear rol</button></form></section>
<section class="panel"><div class="panel-heading"><h2>Últimas 50 operaciones auditadas</h2></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Autor</th><th>Acción</th><th>Entidad</th><th>Registro</th><th>Fecha</th></tr></thead><tbody><?php foreach($activity as $a): ?><tr><td><?= e($a['author'] ?: 'Sistema / sitio público') ?></td><td><?= e(action_label($a['action'])) ?></td><td><?= e($a['entity']) ?></td><td><?= (int)$a['entity_id'] ?></td><td><?= local_date($a['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
